<div class="page-heading"><div><span class="eyebrow">ACTIVITÉ</span><h1>Historique des recherches</h1><p>Retrouvez vos zones analysées et leurs résultats.</p></div><a class="button primary" href="?r=search">＋ Nouvelle recherche</a></div><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Ville / zone</th><th>Catégorie</th><th>Établissements</th><th>Sans site</th><th>Statut</th><th>Date</th><th></th></tr></thead><tbody><?php if(!$searches):?><tr><td colspan="7"><div class="empty-small">Aucune recherche enregistrée.</div></td></tr><?php endif;foreach($searches as $s):?><tr><td><b><?=e($s['ville'])?></b><small class="table-sub"><?=e($s['zone_label'])?></small></td><td><?=e($categories[$s['categorie']]['label']??$s['categorie'])?></td><td><?=$s['nb_trouves']?></td><td><?=$s['nb_sans_site']?></td><td><span class="badge <?= $s['statut']==='terminee'?'no-site':($s['statut']==='erreur'?'status-refuse':'neutral')?>"><?=e(['terminee'=>'Terminée','en_cours'=>'En cours','erreur'=>'Erreur'][$s['statut']]??$s['statut'])?></span></td><td><?=e(date('d/m/Y H:i',strtotime($s['created_at'])))?></td><td><a class="button secondary small" href="?r=results&q=<?=urlencode($s['ville'])?>">Voir résultats</a></td></tr><?php endforeach;?></tbody></table></div></section>
